namespace Bodu.Security.Cryptography;

public partial class Snefru128Tests
{
    // ── Merkle Snefru 2.5a reference known-answer tests (8-pass) ───────────────────────────────
    //
    // Reference: Ralph Merkle's Snefru 2.5a reference distribution (hash2.5a), files testSnefru /
    // correctSnefruOutput, built at the 8-pass security level (SECURITY_LEVEL=8) — the level Bodu
    // implements. GOTCHA: the reference test inputs carry a trailing newline, so the message for the
    // digit string "N" is the bytes of "N" followed by 0x0A (the empty case is a lone 0x0A). Inputs
    // are pinned as exact hex below to make the trailing newline explicit.

    /// <summary>
    /// Verifies that <see cref="Snefru128" /> (128-bit, 8-pass) reproduces the exact digest from Merkle's
    /// Snefru 2.5a reference output for the given newline-terminated input.
    /// </summary>
    /// <param name="messageHex">The input bytes (including the trailing 0x0A) as a hex string.</param>
    /// <param name="expectedHex">The expected 128-bit Snefru digest as uppercase hex.</param>
    [TestMethod]
    [TestCategory("Regression")]
    [DataRow("0A", "D9FCB3171C097FBBA8C8F12AA0906BAD")]
    [DataRow("310A", "44EC420CE99C1F62FEB66C53C24AE453")]
    [DataRow("31320A", "7182051AA852EF6FBA4B6C9C9B79B317")]
    [DataRow("3132330A", "BC3A50AF82BF56D6A64732BC7B050A93")]
    [DataRow("313233340A", "C5B8A04985A8EADFB4331A8988752B77")]
    [DataRow("31323334350A", "D559A2B62F6F44111324F85208723707")]
    [DataRow("3132333435360A", "6CFB5E8F1DA02BD167B01E4816686C30")]
    [DataRow("313233343536370A", "29AA48325F275A8A7A01BA1543C54BA5")]
    [DataRow("31323334353637380A", "BE862A6B68B7DF887EBE00319CBC4A47")]
    [DataRow("3132333435363738390A", "6103721CCD8AD565D68E90B0F8906163")]
    [DataRow("", "56AB6BB21A7A07892D62CB03C41DDE6D")]
    public void ComputeHash_WithMerkleSnefruReferenceVector_ShouldMatchReferenceDigest(string messageHex, string expectedHex)
    {
        byte[] message = Convert.FromHexString(messageHex);

        using var snefru = new Snefru128();
        byte[] actual = snefru.ComputeHash(message);

        Assert.AreEqual(expectedHex, Convert.ToHexString(actual),
            $"Snefru-128 (8-pass) must match Merkle's reference digest for a {message.Length}-byte input.");
    }
}

public partial class Snefru256Tests
{
    // ── Merkle Snefru 2.5a reference known-answer tests (8-pass, OUTPUT_BLOCK_SIZE=8) ──────────
    //
    // Reference: Merkle's Snefru 2.5a distribution, files testSnefru256 / correctSnefru256Output,
    // built at SECURITY_LEVEL=8 with OUTPUT_BLOCK_SIZE=8 (256-bit output). Same trailing-newline
    // convention on the inputs as the 128-bit set.

    /// <summary>
    /// Verifies that <see cref="Snefru256" /> (256-bit, 8-pass) reproduces the exact digest from Merkle's
    /// Snefru 2.5a reference output for the given newline-terminated input.
    /// </summary>
    /// <param name="messageHex">The input bytes (including the trailing 0x0A) as a hex string.</param>
    /// <param name="expectedHex">The expected 256-bit Snefru digest as uppercase hex.</param>
    [TestMethod]
    [TestCategory("Regression")]
    [DataRow("0A", "2E02687F0D45D5B9B50CB68C3F33E6843D618A1ACA2D06893D3EB4E3026B5732")]
    [DataRow("310A", "BFEA4A05A2A2EF15C736D114598A20B9D9BD4D66B661E6B05ECF6A7737BDC58C")]
    [DataRow("31320A", "AC677D69761ADE3F189C7AEF106D5FE7392D324E19CC76D5DB4A2C05F2CC2CC5")]
    [DataRow("3132330A", "061C76AA1DB4A22C0E42945E26C48499B5400162E08C640BE05D3C007C44793D")]
    [DataRow("313233340A", "1E87FE1D9C927E9E24BE85E3CC73359873541640A6261793CE5A974953113F5E")]
    [DataRow("31323334350A", "1B59927D85A9349A87796620FE2FF401A06A7BA48794498EBAB978EFC3A68912")]
    [DataRow("3132333435360A", "28E9D9BC35032B68FAEDA88101ECB2524317E9DA111B0E3E7094107212D9CF72")]
    [DataRow("313233343536370A", "F7FFF4EE74FD1B8D6B3267F84E47E007F029D13B8AF7E37E34D13B469B8F248F")]
    [DataRow("31323334353637380A", "EE7D64B0102B2205E98926613B200185559D08BE6AD787DA717C968744E11AF3")]
    [DataRow("3132333435363738390A", "4CA72639E40E9AB9C0C3F523C4449B3911632D374C124D7702192EC2E4E0B7A3")]
    [DataRow("", "5E8A32ED1998B611F5F096960C65E820DA93A9A424D2715130C1E45483F1839C")]
    public void ComputeHash_WithMerkleSnefruReferenceVector_ShouldMatchReferenceDigest(string messageHex, string expectedHex)
    {
        byte[] message = Convert.FromHexString(messageHex);

        using var snefru = new Snefru256();
        byte[] actual = snefru.ComputeHash(message);

        Assert.AreEqual(expectedHex, Convert.ToHexString(actual),
            $"Snefru-256 (8-pass) must match Merkle's reference digest for a {message.Length}-byte input.");
    }
}
